namespace sv_3dbe333cd43e4e9b86fa8998c91a990f.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// In Blazor Server, "scoped" means one instance per circuit (per browser tab),
/// so each user gets independent state.
/// </summary>
public class ThemeService
{
    private ThemeMode _mode = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Mode
    {
        get => _mode;
        set
        {
            if (_mode == value) return;
            _mode = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@implements IDisposable
@inject ThemeService Theme
@inject IJSRuntime JS

@* 
    This component is rendered as an interactive island inside the static layout.
    It subscribes to ThemeService changes and applies them to the document via JS interop,
    ensuring the entire page reflects the theme regardless of static/interactive boundaries.
*@

@code {
    protected override void OnInitialized()
    {
        Theme.OnChange += HandleThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await ApplyThemeAsync();
        }
    }

    private async void HandleThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            await ApplyThemeAsync();
            StateHasChanged();
        });
    }

    private async Task ApplyThemeAsync()
    {
        var themeValue = Theme.Mode switch
        {
            ThemeMode.Light => "light",
            ThemeMode.Dark => "dark",
            _ => "auto"
        };

        await JS.InvokeVoidAsync("ThemeInterop.apply", themeValue, Theme.AccentColor);
    }

    public void Dispose()
    {
        Theme.OnChange -= HandleThemeChanged;
    }
}

@implements IDisposable
@inject ThemeService Theme

<span class="theme-indicator" title="Current theme">
    @GetIcon() @Theme.Mode
</span>

@code {
    protected override void OnInitialized()
    {
        Theme.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetIcon() => Theme.Mode switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        Theme.OnChange -= HandleThemeChanged;
    }
}

@implements IDisposable
@inject ThemeService Theme

<div class="theme-toggle">
    <button class="btn btn-sm @ButtonClass(ThemeMode.Light)" @onclick="() => SetTheme(ThemeMode.Light)">☀️ Light</button>
    <button class="btn btn-sm @ButtonClass(ThemeMode.Dark)" @onclick="() => SetTheme(ThemeMode.Dark)">🌙 Dark</button>
    <button class="btn btn-sm @ButtonClass(ThemeMode.System)" @onclick="() => SetTheme(ThemeMode.System)">💻 System</button>
</div>

@code {
    protected override void OnInitialized()
    {
        Theme.OnChange += HandleThemeChanged;
    }

    private void SetTheme(ThemeMode mode)
    {
        Theme.Mode = mode;
    }

    private string ButtonClass(ThemeMode mode) =>
        Theme.Mode == mode ? "btn-primary" : "btn-outline-secondary";

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        Theme.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService Theme

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="card p-4 mt-3" style="max-width: 500px;">
    <h5>Theme</h5>
    <ThemeToggle />

    <h5 class="mt-4">Accent Color</h5>
    <div class="d-flex align-items-center gap-3">
        <input type="color" class="form-control form-control-color"
               value="@Theme.AccentColor"
               @onchange="OnAccentChanged" />
        <span>@Theme.AccentColor</span>
    </div>

    <div class="mt-4 p-3 border rounded" style="border-color: var(--accent-color) !important;">
        <strong>Preview:</strong> This border uses the accent color.
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        Theme.OnChange += HandleThemeChanged;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        Theme.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        Theme.OnChange -= HandleThemeChanged;
    }
}

window.ThemeInterop = {
    apply: function (mode, accentColor) {
        const html = document.documentElement;

        // Set color-scheme for browser-level theming
        if (mode === "auto") {
            html.removeAttribute("data-bs-theme");
            html.style.colorScheme = "";
        } else {
            html.setAttribute("data-bs-theme", mode);
            html.style.colorScheme = mode;
        }

        // Apply accent color as CSS custom property
        html.style.setProperty("--accent-color", accentColor);
    }
};

